/// A data message, typed if this crate covers its message.
///
/// ```
/// # let bytes: &[u8] = &[0x0E, 0x20, 0x54, 0x08, 0x12, 0x00, 0x00, 0x00, 0x2E, 0x46, 0x49, 0x54, 0x39, 0x04, 0x40, 0x00, 0x00, 0x14, 0x00, 0x02, 0xFD, 0x04, 0x86, 0x03, 0x01, 0x02, 0x00, 0x00, 0xCA, 0x9A, 0x3B, 0x8E, 0x20, 0xD3];
/// use zerofit::{Decoder, Record};
/// use zerofit_profile::Message;
///
/// for record in Decoder::new(bytes) {
///     if let Record::Data(msg) = record? {
///         if let Message::Record(r) = Message::new(msg) {
///             assert_eq!(r.heart_rate(), Some(142));
///         }
///     }
/// }
/// # Ok::<(), zerofit::Error>(())
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum Message<'a> {
    /// A `file_id` message.
    FileId(FileId<'a>),
    /// A `activity` message.
    Activity(Activity<'a>),
    /// A `session` message.
    Session(Session<'a>),
    /// A `lap` message.
    Lap(Lap<'a>),
    /// A `record` message.
    Record(Record<'a>),
    /// A `event` message.
    Event(Event<'a>),
    /// A `device_info` message.
    DeviceInfo(DeviceInfo<'a>),
    /// A `hrv` message.
    Hrv(Hrv<'a>),
    /// A message this crate has no typed view for.
    Other(DataMessage<'a>),
}

impl<'a> Message<'a> {
    /// Wraps `msg` in its typed view.
    #[must_use]
    pub fn new(msg: DataMessage<'a>) -> Self {
        match msg.global_message_number() {
            0 => Self::FileId(FileId(msg)),
            34 => Self::Activity(Activity(msg)),
            18 => Self::Session(Session(msg)),
            19 => Self::Lap(Lap(msg)),
            20 => Self::Record(Record(msg)),
            21 => Self::Event(Event(msg)),
            23 => Self::DeviceInfo(DeviceInfo(msg)),
            78 => Self::Hrv(Hrv(msg)),
            _ => Self::Other(msg),
        }
    }

    /// The underlying raw message.
    #[must_use]
    pub const fn raw(&self) -> &DataMessage<'a> {
        match self {
            Self::FileId(m) => &m.0,
            Self::Activity(m) => &m.0,
            Self::Session(m) => &m.0,
            Self::Lap(m) => &m.0,
            Self::Record(m) => &m.0,
            Self::Event(m) => &m.0,
            Self::DeviceInfo(m) => &m.0,
            Self::Hrv(m) => &m.0,
            Self::Other(m) => m,
        }
    }
}

